  SELECT payload->>'review_sha256' INTO presentation_review FROM mission_public_owner.public_qualification_attestations_v1 WHERE payload_sha256=presentation_compat AND payload->>'current_release_sha256'=csha;
  SELECT * INTO presentation_asset FROM mission_public_owner.public_qualification_attestations_v1 WHERE release_sha256=mission_factory_owner.sha(jsonb_build_object('schema_version','human-presentation-successor-key/1','current_release_sha256',presentation_current));
 presentation_ok:=(presentation_asset.created_by='postgres'::name AND presentation_asset.payload_sha256=mission_factory_owner.sha(presentation_asset.payload)
 AND mission_factory_owner.keys_exact_v2(presentation_asset.payload,ARRAY['schema_version','current_release_sha256','compatibility_sha256','predecessor_release_sha256','predecessor_compatibility_sha256','predecessor_positive_sha256','predecessor_lease_sha256','client_binding','edge_binding','patch_contract','source_review_sha256','published_commit','published_land_sha256','publication_proof_sha256']) IS TRUE
 AND presentation_asset.payload->>'schema_version'='human-presentation-successor/1'
 AND presentation_asset.payload->>'current_release_sha256'=presentation_current AND presentation_asset.payload->>'compatibility_sha256'=presentation_compat
 AND presentation_asset.payload->>'predecessor_release_sha256'='a65259745010e998aee598a7b85f23ac3e7e2645d4c8628eead2ee2767c33c21' AND presentation_asset.payload->>'predecessor_compatibility_sha256'='20967513ed9c443d83db984345a394388502eea16bf175baa9f408e9b21e4ced'
 AND presentation_asset.payload->>'predecessor_positive_sha256'='3ba86c144d5e64350a4739aef94c298cbba69d9950de5d31f36087c8df97801c' AND presentation_asset.payload->>'predecessor_lease_sha256'='575472d6c9fdd9fd9e4ee9fbb257e0c3b8dfb07f6af82f6ab81c00036eb2e869'
 AND presentation_asset.payload->'client_binding'='{"files":[{"path":"land.html","bytes":2323604,"sha256":"8f89a7234ba40cfda902dc4dc507f2581540ee4f464f4beaa7f21ccc590c67a6"},{"path":"admin.html","bytes":471902,"sha256":"89cbcdb1e86a0ab005ca09d502b187a6e5e6602e9cdfee4e1b9f1ff785937a8b"},{"path":"mf-human-ordinary-consumer-d1e20064f4111928622b8b485e3efdacfb5d852fda9019c406cfbfe034ed410c.mjs","bytes":64505,"sha256":"d1e20064f4111928622b8b485e3efdacfb5d852fda9019c406cfbfe034ed410c"}],"copy_build":"HUMAN33-INLINE-WORKSPACE-006","ordinary_build":"HUMAN-ORDINARY-AGG1-INLINE-001","schema_version":"human-ordinary-published-client/1","application_commit":"fdaa5759fdcb2b1342141fbc2efc2d5cd16d1837"}'::jsonb
 AND presentation_asset.payload->'edge_binding'=presentation_tuple#>'{edge,bindings}'
 AND EXISTS(SELECT 1 FROM mission_public_owner.release_admissions_v1 presentation_shadow JOIN mission_public_owner.release_admissions_v1 presentation_live ON presentation_live.release_sha256=presentation_current WHERE presentation_shadow.release_sha256=presentation_asset.release_sha256 AND presentation_shadow.public_enabled=false AND presentation_shadow.staff_evidence_ref='SOURCE_RECORD_ONLY:HUMAN_PRESENTATION_SUCCESSOR' AND (to_jsonb(presentation_shadow)-'release_sha256'-'created_at'-'staff_evidence_ref'-'public_enabled') IS NOT DISTINCT FROM (to_jsonb(presentation_live)-'release_sha256'-'created_at'-'staff_evidence_ref'-'public_enabled'))
 AND presentation_asset.payload->>'patch_contract'='human-actor-display-name-server-gated/1'
 AND presentation_asset.payload->>'source_review_sha256'=presentation_review
 AND presentation_asset.payload->>'published_commit'='fdaa5759fdcb2b1342141fbc2efc2d5cd16d1837' AND presentation_asset.payload->>'published_land_sha256'='8f89a7234ba40cfda902dc4dc507f2581540ee4f464f4beaa7f21ccc590c67a6'
 AND coalesce(presentation_asset.payload->>'publication_proof_sha256','')~'^[0-9a-f]{64}$'
 AND presentation_asset.positive_staff_evidence_ref=('PUBLISHED_ASSET_PROOF:'||(presentation_asset.payload->>'publication_proof_sha256'))
 AND EXISTS(SELECT 1 FROM mission_public_owner.public_qualification_attestations_v1 presentation_oldcp WHERE presentation_oldcp.payload_sha256='20967513ed9c443d83db984345a394388502eea16bf175baa9f408e9b21e4ced' AND presentation_oldcp.created_by='postgres'::name AND presentation_oldcp.payload_sha256=mission_factory_owner.sha(presentation_oldcp.payload) AND presentation_oldcp.payload->>'current_release_sha256'='a65259745010e998aee598a7b85f23ac3e7e2645d4c8628eead2ee2767c33c21')
 AND EXISTS(SELECT 1 FROM mission_public_owner.public_qualification_attestations_v1 presentation_oldpos WHERE presentation_oldpos.payload_sha256='3ba86c144d5e64350a4739aef94c298cbba69d9950de5d31f36087c8df97801c' AND presentation_oldpos.created_by='postgres'::name AND presentation_oldpos.payload_sha256=mission_factory_owner.sha(presentation_oldpos.payload) AND presentation_oldpos.payload->>'capability_sha256'='a65259745010e998aee598a7b85f23ac3e7e2645d4c8628eead2ee2767c33c21')
 AND EXISTS(SELECT 1 FROM mission_public_owner.public_qualification_attestations_v1 presentation_oldlease WHERE presentation_oldlease.payload_sha256='575472d6c9fdd9fd9e4ee9fbb257e0c3b8dfb07f6af82f6ab81c00036eb2e869' AND presentation_oldlease.created_by='postgres'::name AND presentation_oldlease.payload_sha256=mission_factory_owner.sha(presentation_oldlease.payload) AND presentation_oldlease.payload->>'current_release_sha256'='a65259745010e998aee598a7b85f23ac3e7e2645d4c8628eead2ee2767c33c21')) IS TRUE;
  SELECT * INTO presentation_ui FROM mission_public_owner.public_qualification_attestations_v1 WHERE release_sha256=mission_factory_owner.sha(jsonb_build_object('schema_version','human-presentation-ui-positive-key/1','current_release_sha256',csha));
  IF presentation_ok IS TRUE AND presentation_ui.created_by='postgres'::name AND presentation_ui.payload_sha256=mission_factory_owner.sha(presentation_ui.payload)
  AND mission_factory_owner.keys_exact_v2(presentation_ui.payload,ARRAY['schema_version','current_release_sha256','asset_proof_sha256','session_id','terminal_receipt_id','render_proof_sha256','review_sha256','provider_calls','protected_before_md5','protected_after_md5']) IS TRUE
  AND presentation_ui.payload->>'schema_version'='human-presentation-ui-positive/1' AND presentation_ui.payload->>'current_release_sha256'=csha
  AND presentation_ui.positive_staff_evidence_ref=('UI_RENDER_PROOF:'||(presentation_ui.payload->>'render_proof_sha256'))
  AND presentation_ui.authorized_test_manifest_ref=ct#>>'{config,policy,custom_staff_manifest_ref}'
  AND presentation_ui.payload->>'asset_proof_sha256'=presentation_asset.payload_sha256 AND presentation_ui.payload->>'review_sha256'=presentation_review
  AND coalesce(presentation_ui.payload->>'render_proof_sha256','')~'^[0-9a-f]{64}$' AND presentation_ui.payload->'provider_calls'='0'::jsonb
  AND presentation_ui.payload->>'protected_before_md5'='d41adde267a202a8ff4c6c194eb0a09f' AND presentation_ui.payload->>'protected_after_md5'=presentation_ui.payload->>'protected_before_md5'
  AND EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources presentation_q JOIN public.master_v2_sessions presentation_m ON presentation_m.id=presentation_q.session_id JOIN mission_factory_owner.quest_terminal_receipts presentation_tr ON presentation_tr.id=presentation_q.terminal_receipt_id JOIN mission_factory_owner.quest_arcs presentation_a ON presentation_a.id=presentation_q.arc_id WHERE presentation_q.session_id=(presentation_ui.payload->>'session_id')::uuid AND presentation_q.session_id<>'9845891c-2e02-5ba6-8b45-68ff9f2fe268'::uuid AND presentation_q.state='terminal' AND presentation_q.execution_context='staff_simulation' AND presentation_q.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND presentation_m.owner_kind='human' AND presentation_m.location_id=presentation_q.location_id AND presentation_m.stato='chiusa' AND presentation_m.closed_at IS NOT NULL AND presentation_tr.id=(presentation_ui.payload->>'terminal_receipt_id')::uuid AND presentation_tr.outcome='success' AND presentation_tr.publication_id IS NOT NULL AND presentation_a.state='completed' AND presentation_q.availability_scope='public' AND presentation_q.public_release_sha256='5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366' AND cardinality(presentation_a.execution_auth_ids)=2 AND presentation_a.execution_auth_ids @> ARRAY['f0856d53-83a6-4de0-bc0c-12c87916e665','b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b']::uuid[] AND cardinality(presentation_a.member_character_ids)=2 AND presentation_a.member_character_ids @> ARRAY['6bceee99-974f-426b-8d92-38b43b4a4267','f335b077-34a1-41c3-94aa-58ec674b649b']::uuid[] AND presentation_a.draft_id='48b332c1-b454-554a-9fc6-3de6c095e86f'::uuid AND presentation_a.draft_version=3 AND presentation_a.source_sha256='ec99725d2587b820a03c95361e30656fa6a116c7cf4d55d0f46ffcdb4c56e3f8'
   AND EXISTS(SELECT 1 FROM mission_public_owner.public_qualification_attestations_v1 presentation_sp WHERE presentation_sp.release_sha256=mission_factory_owner.sha(jsonb_build_object('schema_version','human-custom-source-key/1','publication_request',presentation_a.publication_request)) AND presentation_sp.created_by='postgres'::name AND presentation_sp.payload_sha256=mission_factory_owner.sha(presentation_sp.payload) AND (presentation_sp.payload->>'capability_sha256'=csha OR (presentation_sp.payload->>'capability_sha256'='580be4072a649946a94c2b344519266113eb4bec18d20eb6e4acbac4d27c2a6e' AND mission_factory_owner.human_staff_context_records_v1(observed,csha,presentation_a.id,'continuity_historical',g) IS TRUE)) AND presentation_sp.payload->>'arc_id'=presentation_a.id::text)
   AND EXISTS(SELECT 1 FROM public.mission_run_outbox presentation_ox WHERE presentation_ox.master_session_id=presentation_q.session_id AND presentation_ox.event_id=presentation_tr.close_event_id AND presentation_ox.state='published' AND presentation_ox.publication_id=presentation_tr.publication_id)
   AND (SELECT count(*) FROM public.master_v2_participants presentation_pc WHERE presentation_pc.session_id=presentation_q.session_id)=2
   AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts presentation_dr WHERE presentation_dr.master_session_id=presentation_q.session_id)
   AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items presentation_wi WHERE presentation_wi.master_session_id=presentation_q.session_id)
   AND NOT EXISTS(SELECT 1 FROM public.combat_v2_sessions presentation_cs JOIN public.combat_v2_resource_ledger presentation_rl ON presentation_rl.session_id=presentation_cs.id WHERE presentation_cs.master_session_id=presentation_q.session_id AND presentation_rl.is_simulated IS DISTINCT FROM true)
   AND NOT EXISTS(SELECT 1 FROM public.master_v2_participants presentation_p WHERE presentation_p.session_id=presentation_q.session_id AND (presentation_p.left_at IS NULL OR presentation_p.engagement_state IS DISTINCT FROM 'concluso')))
  THEN
   SELECT * INTO pos FROM mission_public_owner.public_qualification_attestations_v1 WHERE payload_sha256='3ba86c144d5e64350a4739aef94c298cbba69d9950de5d31f36087c8df97801c' AND payload->>'capability_sha256'='a65259745010e998aee598a7b85f23ac3e7e2645d4c8628eead2ee2767c33c21';
   presentation_inherited:=true;
  END IF;
 END IF;
 IF NOT coalesce(force_staff,false) AND ad.public_enabled AND pos.created_by='postgres'::name AND pos.payload_sha256=mission_factory_owner.sha(pos.payload)
 AND mission_factory_owner.keys_exact_v2(pos.payload,ARRAY['schema_version','capability_sha256','session_id','terminal_receipt_id','encounter_id','report_id','protected_before_md5','protected_after_md5','provider_calls'])
 AND pos.payload->>'schema_version'='human-custom-positive-staff/1' AND pos.payload->>'capability_sha256'=(CASE WHEN presentation_inherited THEN 'a65259745010e998aee598a7b85f23ac3e7e2645d4c8628eead2ee2767c33c21' ELSE csha END) AND pos.payload->'provider_calls'='0'::jsonb
 AND coalesce(pos.payload->>'protected_before_md5','')~'^[0-9a-f]{32}$' AND pos.payload->>'protected_before_md5'=pos.payload->>'protected_after_md5' THEN
 SELECT * INTO src FROM mission_factory_owner.quest_run_sources WHERE session_id=(pos.payload->>'session_id')::uuid;
 SELECT * INTO ar FROM mission_factory_owner.quest_arcs WHERE id=src.arc_id;
 SELECT * INTO tr FROM mission_factory_owner.quest_terminal_receipts WHERE id=(pos.payload->>'terminal_receipt_id')::uuid;
 IF src.state='terminal' AND src.availability_scope='public' AND src.execution_context='staff_simulation' AND src.public_release_sha256='5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366' AND src.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
 AND src.terminal_receipt_id=tr.id AND tr.session_id=src.session_id AND tr.source_sha256=src.source_sha256 AND tr.outcome='success' AND tr.publication_id IS NOT NULL AND ar.state='completed' AND cardinality(ar.execution_auth_ids)=2 AND cardinality(ar.member_character_ids)=2
 AND EXISTS(SELECT 1 FROM mission_public_owner.public_qualification_attestations_v1 sp WHERE sp.release_sha256=mission_factory_owner.sha(jsonb_build_object('schema_version','human-custom-source-key/1','publication_request',ar.publication_request)) AND sp.created_by='postgres'::name AND sp.payload->>'schema_version'='human-custom-source/1' AND (CASE WHEN presentation_inherited THEN sp.payload_sha256='477b4631c0c8f1fb3db585edbdc12e32ee9420ffb9dd9f47234cad984a1679c1' AND src.session_id='9845891c-2e02-5ba6-8b45-68ff9f2fe268'::uuid AND tr.id='535535b1-340e-4472-a4a0-9d1914fc739f'::uuid AND ar.id='22765216-5f14-573f-86e4-60c402941ec9'::uuid ELSE (sp.payload->>'capability_sha256'=csha OR (sp.payload->>'capability_sha256' IS DISTINCT FROM csha AND (mission_factory_owner.human_staff_context_records_v1(observed,csha,ar.id,'continuity_historical',g) OR mission_factory_owner.human_staff_lease_valid_verified_v1(observed,ar.id,false,p_context)))) END) AND sp.payload->>'source_sha256'=ar.source_sha256 AND sp.payload->>'arc_id'=ar.id::text AND sp.payload_sha256=mission_factory_owner.sha(sp.payload))
 AND EXISTS(SELECT 1 FROM public.master_v2_sessions mm WHERE mm.id=src.session_id AND mm.owner_kind='human' AND mm.stato='chiusa' AND mm.closed_at IS NOT NULL)
 AND EXISTS(SELECT 1 FROM public.mission_run_outbox ox WHERE ox.event_id=tr.close_event_id AND ox.master_session_id=src.session_id AND ox.state='published' AND ox.publication_id=tr.publication_id)
 AND EXISTS(SELECT 1 FROM public.combat_v2_sessions cs JOIN public.combat_v2_rounds cr ON cr.session_id=cs.id JOIN public.combat_v2_round_reports rp ON rp.round_id=cr.id JOIN mission_generic_owner.regia_human_windows_v1 hw ON hw.master_session_id=src.session_id AND hw.encounter_id=cs.id AND hw.source_report_id=rp.id AND hw.source_report_sha256=rp.mechanics_sha256 AND hw.message_id=rp.message_id WHERE cs.id=(pos.payload->>'encounter_id')::uuid AND cs.master_session_id=src.session_id AND cs.state='chiuso' AND cs.closed_at IS NOT NULL AND rp.id=(pos.payload->>'report_id')::uuid AND rp.narration_state='pubblicata' AND rp.values_written=false AND hw.state='published' AND (SELECT count(*) FROM public.combat_v2_narratives nn WHERE nn.report_id=rp.id AND nn.kind='fato_umano')=1)
 AND EXISTS(SELECT 1 FROM public.combat_v2_provider_instances_v1 pi JOIN public.nb_mechanical_versions cv ON cv.id=pi.mechanical_version_ref WHERE pi.session_id=(pos.payload->>'encounter_id')::uuid AND pi.provider='ninja_book' AND cv.profile_kind='npc_custom' AND cv.review_state='approved' AND pi.source_sha256=cv.content_sha256 AND pi.snapshot_sha256=public.combat_v2_sha256(pi.snapshot))
 AND EXISTS(SELECT 1 FROM mission_factory_owner.quest_reward_decisions_v2 rd WHERE rd.arc_id=ar.id AND rd.terminal_receipt_id=tr.id AND rd.effect_mode='simulation' AND rd.receipt->>'state'='simulated' AND rd.receipt->>'computed_xp_per_recipient'='30' AND rd.receipt->>'effective_xp_per_recipient'='0' AND rd.receipt->>'ryo_per_recipient'='0' AND rd.receipt->'items'='[]'::jsonb)
 AND NOT EXISTS(SELECT 1 FROM public.combat_v2_resource_ledger rl WHERE rl.session_id=(pos.payload->>'encounter_id')::uuid AND rl.is_simulated IS DISTINCT FROM true)
 AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts zpd WHERE zpd.master_session_id=src.session_id)
 AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_attempts zpa JOIN mission_narrative_internal.dispatch_receipts zpr ON zpr.id=zpa.receipt_id WHERE zpr.master_session_id=src.session_id)
 AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items zpw WHERE zpw.master_session_id=src.session_id)
 THEN mode:='public_real';END IF;
 END IF;
 IF mode IS NULL AND NOT p_public AND own_draft::text=ct#>>'{config,policy,custom_native_draft_id}'
 AND coalesce(ct#>>'{config,policy,custom_staff_expires_at}','')<>'' AND clock_timestamp()<(ct#>>'{config,policy,custom_staff_expires_at}')::timestamptz
 AND mission_factory_owner.c416_kind_live_v1() IS TRUE AND mission_factory_owner.c444_enabled_v1() IS TRUE
 AND cardinality((SELECT allowed_auth_ids FROM mission_factory_owner.c416_kind_admission WHERE singleton))=2
 AND EXISTS(SELECT 1 FROM mission_factory_owner.c416_kind_admission nk WHERE nk.singleton AND auth.uid()=ANY(nk.allowed_auth_ids))
 AND EXISTS(SELECT 1 FROM mission_factory_owner.drafts nd WHERE nd.id=own_draft AND nd.author_user=auth.uid() AND nd.state IN('draft','previewed') AND nd.document->>'schema_version'='mission-factory-draft/2' AND nd.document->>'content_kind'='quest_ai' AND nd.document_sha256=mission_factory_owner.sha(nd.document))
 THEN mode:='staff_simulation';END IF;
 IF mode IS NULL AND NOT p_public AND g.public_staff_enabled AND own_draft=g.public_staff_draft_id
 AND g.public_staff_release_sha256='5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366' AND g.public_staff_test_manifest_ref=ct#>>'{config,policy,custom_staff_manifest_ref}'
 AND (coalesce(ct#>>'{config,policy,custom_staff_expires_at}','')<>'' AND clock_timestamp()<(ct#>>'{config,policy,custom_staff_expires_at}')::timestamptz OR EXISTS(SELECT 1 FROM mission_factory_owner.quest_arcs lease_cap_arc WHERE lease_cap_arc.draft_id=own_draft AND mission_factory_owner.human_staff_lease_valid_verified_v1(observed,lease_cap_arc.id,true,p_context)))
 AND mission_factory_owner.c416_kind_live_v1() IS TRUE AND mission_factory_owner.c444_enabled_v1() IS TRUE
 AND cardinality(g.allowed_auth_ids)=2 AND auth.uid()=ANY(g.allowed_auth_ids)
 AND mission_factory_owner.human_ordinary_authority_verified_v1(own_draft,g.public_staff_draft_version,g.public_staff_source_sha256,p_context)->>'execution_context'='staff_simulation'
 THEN mode:='staff_simulation';END IF;
 IF mode IS NULL THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('schema_version','human-custom-capability/1','capability_sha256',csha,'base_release_sha256','5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366','execution_context',mode,'staff_manifest_ref',ct#>>'{config,policy,custom_staff_manifest_ref}','draft_id',own_draft);
END
$function$;
